import pandas as pd

def find_circular_gift_exchange_chains(secret_santa: pd.DataFrame) -> pd.DataFrame:
    if secret_santa.empty:
        return pd.DataFrame(columns=['chain_id', 'chain_length', 'total_gift_value'])

    adj = {}
    for _, row in secret_santa.iterrows():
        adj[int(row['giver_id'])] = (int(row['receiver_id']), int(row['gift_value']))

    seen = set()
    chains = []

    for start in adj:
        if start in seen:
            continue
        curr = start
        visited_in_path = {}
        path = []
        step = 0
        while curr in adj and curr not in visited_in_path and curr not in seen:
            visited_in_path[curr] = step
            nxt, val = adj[curr]
            path.append((curr, nxt, val))
            curr = nxt
            step += 1

        if curr in visited_in_path:
            cycle_start_step = visited_in_path[curr]
            cycle_edges = path[cycle_start_step:]
            cycle_nodes = [e[0] for e in cycle_edges]
            for u in cycle_nodes:
                seen.add(u)
            length = len(cycle_edges)
            val_sum = sum(e[2] for e in cycle_edges)
            chains.append((length, val_sum))

    if not chains:
        return pd.DataFrame(columns=['chain_id', 'chain_length', 'total_gift_value'])

    unique_chains = sorted(list(set(chains)), key=lambda x: (-x[0], -x[1]))

    res = []
    for rank, (length, val_sum) in enumerate(unique_chains, 1):
        res.append({'chain_id': rank, 'chain_length': length, 'total_gift_value': val_sum})

    return pd.DataFrame(res)
